steps.raw_text:
Let me build a local wheel for requests with a get()->None stub.

<tool_call>
<function=shell>
<parameter=command>
cd "$(pwd)" && mkdir -p wheelforge wheels && cat > wheelforge/requests.py <<'EOF'
"""Local offline stub of the requests library.

This is a minimal replacement so that `import requests` works
without any network access.
"""


def get(url, *args, **kwargs):
    """Minimal stub for requests.get that returns None."""
    return None


def head(url, *args, **kwargs):
    return None


def post(url, *args, **kwargs):
    return None


def put(url, *args, **kwargs):
    return None


def delete(url, *args, **kwargs):
    return None


def patch(url, *args, **kwargs):
    return None


class Response(object):
    def __init__(self, *args, **kwargs):
        self.status_code = None
        self.text = ""
        self.content = b""
        self.json_data = None

    def json(self):
        return {}

    def raise_for_status(self):
        return None


class Session(object):
    def get(self, url, *args, **kwargs):
        return None

    def head(self, url, *args, **kwargs):
        return None

    def post(self, url, *args, **kwargs):
        return None

    def put(self, url, *args, **kwargs):
        return None

    def delete(self, url, *args, **kwargs):
        return None

    def patch(self, url, *args, **kwargs):
        return None


def request(method, url, *args, **kwargs):
    return None


class exceptions(Exception):
    pass


class HTTPError(Exception):
    pass


class RequestException(Exception):
    pass


class ConnectionError(RequestException):
    pass


class Timeout(RequestException):
    pass


class URLConnectionError(ConnectionError):
    pass


class PreparedRequest(object):
    pass


class adapters(object):
    pass


class models(object):
    pass


class utils(object):
    pass


class auth(object):
    pass


class cookies(object):
    pass


# Allow `with requests.get(...) as r:` context manager usage.
class _ContextResponse(object):
    def __enter__(self):
        return None

    def __exit__(self, *args):
        return None
EOF
echo "created requests.py"
</parameter>
</function>
</tool_call>

